# GNU ld / LLD version script for libhaze.so.
#
# libhaze statically absorbs the niobium OpenFHE 1.4.2 fork + libnbfhetch + the
# replay bridge. To let it coexist in one process with another OpenFHE (e.g.
# FIDESlib's statically-linked 1.5.1), every absorbed symbol must be hidden;
# only haze's public C ABI may be exported. The C ABI is exactly the set of
# `extern "C"` entry points whose names start with `haze` (hazeMalloc, hazeAdd,
# hazeReplayBridgeInitCryptoContext, ...). Internal C++ mangles to `_ZN4haze...`
# (does not start with `haze`) and is localized along with all lbcrypto/niobium
# symbols. Paired with -Wl,--exclude-libs,ALL on the link line.
#
# The version-node name `HAZE_1.0` is part of the published, versioned ABI of
# libhaze.so once shipped — renaming or removing it is an ABI break. Add new
# nodes (HAZE_1.1, ...) rather than mutating this one.
HAZE_1.0 {
  global:
    haze*;
  local:
    *;
};

# The rule: a symbol that is new, or whose signature/ABI changes under a name
# already in an earlier node, is listed BY EXACT NAME in the node of the
# release that introduces it — never left to an earlier node's `haze*`
# wildcard. That listing is what wins: an explicit name in a later node binds
# the symbol to that node instead of an earlier node's wildcard match.
# HAZE_1.0's wildcard keeps every symbol the golden file lists at HAZE_1.0;
# the rule applies from HAZE_1.1 on.
# Enforced automatically, for every exported symbol (not just the ones any
# one change touches): scripts/check_symbol_leak.sh diffs the full
# name@@VERSION set against the golden scripts/haze_symbol_versions.txt, so a
# symbol landing in the wrong node — this one or a later one that forgets to
# update the golden file — fails that check. hazeGetLastErrorMessage is new
# here (never shipped in 1.0).
HAZE_1.1 {
  global:
    hazeGetLastErrorMessage;
} HAZE_1.0;
